
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EPROMHQ"."VAC_WINTER_DATA_EMP_AND_FAMILY_ESTB3AD_V" ("M", "WINTER_APP_ID", "EMP_NO", "FULL_NAME", "RELATION_DESC", "PROJECT_NAME", "JOB_NAME", "GRADE_NAME", "GRADE_DATE", "BENEFIT_TEXT", "HIRE_DATE", "BIRTH_DATE", "AGE_DAYS_25_1_2025", "AGE_MONTHS_25_1_2025", "AGE_YEARS_25_1_2025", "ROOM_CLASS", "NUM_OF_ROOMS", "LOCATION_ID", "TRANSPORTATION_TYPE", "MOBILE_NO", "WHATS_NO", "NOTES", "ATTACH1", "ATTACH2", "ATTACH3", "IS_APOLOGY") AS
  select a."M",A.WINTER_APP_ID,a."EMP_NO",a."FULL_NAME",a."RELATION_DESC",a."PROJECT_NAME",a."JOB_NAME",a."GRADE_NAME"
  ,a."GRADE_DATE",a."BENEFIT_TEXT",a."HIRE_DATE",a."BIRTH_DATE",a."AGE_DAYS_25_1_2025",a."AGE_MONTHS_25_1_2025"
  ,a."AGE_YEARS_25_1_2025",a."ROOM_CLASS",a."NUM_OF_ROOMS",a."LOCATION_ID",a."TRANSPORTATION_TYPE",a."MOBILE_NO",
  a."WHATS_NO",a."NOTES",k.ATTACH1, k.ATTACH2, k.ATTACH3 ,a.IS_APOLOGY
  from VAC_WINTER_2026_Estb3ad_V a left join VAC_WINTER_ATTACHMENT_EMP_AND_FAMILY_V k on a.Full_name = k.RELATIVE_NAME
  where  a.IS_APOLOGY <> 'معتذر';
